# caps on what is handed back to the model
MAX_PLAYERS = 25
MAX_H2H_SETS = 30
MAX_TOURNAMENTS = 30
MAX_ENTRANTS = 200

_INSTRUCTIONS = clean_f_str(
    """
    For a competitive Smash Ultimate player's picks, the sets two players played, tournaments and
    entrants, use these tools. The data is tournament sets reported on start.gg, not docs/.
    - "stats for <player>", "what does <player> play": get_player_usage with their tag. Add
      vs_characters for "what do they pick against Steve" (several for "against Steve or Pac-Man":
      games against any of them count).
    - Tags aren't unique. Check `lookup`: `match_type` is tag_exact, tag_any_case, player_id or
      profile; `tied_matches` > 1 means several players share the tag and the one with the most
      events was picked. Say who was picked (tag, region, events) and, on a tie, offer find_players
      to choose another, then call again with that player's `player_id`.
    - ALWAYS say what the numbers cover, from `window`: it is the player's newest sets (one quick
      look, about 3-4 events), not a span of months. Give the real dates (`first_date` to
      `last_date`) and the counts ("23 sets from 3 events, 90 games"), and call it their recent
      play, not their overall habits.
    - `sets` (30 by default) is how far back get_player_usage reads. Keep 30 unless the user asks
      for a longer history ("the last couple of months", "since a tournament"): then 60-150, one
      start.gg request per 30. Say the span you got; offer more rather than taking it unasked.
    - `setting` says which events were counted (all, offline, online). Online and in-person
      picks can differ, so when it isn't 'all', say which one the numbers are for. Each event in
      `last_events` has `online`.
    - `recent` is every game; `game_1` is what they open a set with; `last_events` lists their
      newest events with the characters used at each (unit='events' there: "Roy at 3 of 8 events",
      never "3 games").
    - Stages: `starters` (game 1), `counterpicks` (the game after one they lost, so their pick),
      `taken_to` (the game after one they won, the opponent's pick). Many brackets report no
      stages, so these are often small or empty: give the game count, or say there is no stage data.
    - `switches` is how often they change character inside a set. Phrase it as a habit ("came
      back as another character in 16 of 103 games after dropping one"), not as a record.
    - usage_pct is 0-100. Mention counts: small samples (eg 2 games) mean little.
    - get_head_to_head lists the games two players played (characters, stages, event, round).
      find_tournaments searches events by place and date; get_event_entrants lists who is entered.
    - Facts only: the user is prepping for opponents and doesn't want to judge how good they are.
      These tools give no winners, scores, win-loss records, seeds or placements on purpose. Don't bring
      those up from memory or other sources either, unless the user asks for them directly; if
      they do, say these tools don't provide results.
    - The user's app draws get_player_usage as a chart, so don't repeat every number: give the
      window, the main picks and anything notable.
    """
)

_T = TypeVar("_T")


def _run(work: Coroutine[Any, Any, _T]) -> _T:
    """Run a data-layer coroutine from a (sync) tool, mapping failures for the model

    Sync on purpose: pydantic-ai runs sync tools in a worker thread, and the app's tool forms
    call these functions the same way, so there is never a running event loop here.
    """
    try:
        # every request the tool makes shares one log group (eg 'player_usage-3f9a1c')
        with log_group(getattr(work, "__name__", "tool")):
            return asyncio.run(work)
    except PlayerLookupError as e:
        raise ModelRetry(f"{e}. Use find_players to look up a tag, or ask the user for a start.gg profile url.") from e
    except ValueError as e:  # bad input: unknown event, bad date
        raise ModelRetry(f"{e}.") from e
    # final, not a retry: a second failed call would end the whole run with an error
    except startgg.StartggError as e:
        raise ToolFailed(f"{e} Tell the user start.gg data isn't available right now and why.") from e
    except httpx2.HTTPError as e:
        raise ToolFailed(f"start.gg could not be reached ({e}). Tell the user to try again later.") from e


def _date(text: str, name: str) -> dt.datetime | None:
    if not text.strip():
        return None
    try:
        return dt.datetime.fromisoformat(text.strip()).replace(tzinfo=dt.UTC)
    except ValueError as e:
        raise ModelRetry(f"{name} must be a date like '2026-12-01', got {text!r}.") from e


def find_players(tag: str) -> list[PlayerCandidate]:
    """Search Smash Ultimate players by tag, most events first.

    Matches substrings in any case, so 'luke' also finds 'Lukedub'. Use it to pick among
    players sharing a tag, then pass the chosen `player_id` as `player` to the other tools.

    Args:
        tag: player tag or part of one, eg 'Luke'.
    """
    return _run(derived.find_players(tag))[:MAX_PLAYERS]


def get_player_usage(
    player: str,
    # a list of a character type: validated, listed in the schema, the choice input (several
    # picks) in the app's form (tool_forms: any list[<choices>] parameter gets one)
    vs_characters: list[CharGroup] | None = None,
    # choices in the type, so the tool's schema lists them (for the model and the app's form)
    setting: Setting = "all",
    sets: SetCount = 30,
) -> PlayerUsage:
    """Get which characters and stages a player picks, from their newest start.gg sets.

    Returns character usage overall, in game 1 and per recent event, stage usage (starters,
    counterpicks, taken to) and how often they switch character within a set, over the newest
    ~30 sets (about 3-4 events). `window` says what the numbers cover.

    Args:
        player: a tag (eg 'Sparg0'), a start.gg player id (eg '158026') or a start.gg profile
            url. For a shared tag the player with the most events is picked (see `lookup`).
        vs_characters: only count games against these characters (any of them), eg
            ['steve'] or ['steve', 'pac_man']; 'pokemon_trainer' for the Pokemon Trainer pick.
            Leave unset for all games.
        setting: 'all' (default), 'offline' for in-person events only, or 'online' for online
            events only. Use 'offline' when the user asks about offline / in-person / LAN play.
        sets: how many of their newest sets to read: 30 (default, about 3-4 events) up to 150.
            Each 30 is one more start.gg request; ask for more only when the user wants a
            longer history.
    """
    requests = sets // startgg.USAGE_PER_PAGE
    return _run(derived.player_usage(player, vs_characters=vs_characters, setting=setting, requests=requests))


def get_head_to_head(player_1: str, player_2: str) -> TableResult:
    """List the games two players played against each other on start.gg, newest set first.

    One row per game: date, tournament, event, round, online, game number, each player's
    character and the stage. A set reported without games is one row with empty characters.

    Args:
        player_1: a tag, start.gg player id or profile url, eg 'Sparg0'.
        player_2: the opponent, same forms, eg 'acola'.
    """
    h2h = _run(derived.head_to_head(player_1, player_2, max_sets=MAX_H2H_SETS))
    first, second = h2h.player_1.tag, h2h.player_2.tag
    rows = [
        {
            "date": s.date,
            "tournament": s.tournament,
            "event": s.event,
            "round": s.round,
            "online": s.online,
            "game": game.number if game else None,
            f"{first}_character": game.character_1 if game else None,
            f"{second}_character": game.character_2 if game else None,
            "stage": game.stage if game else None,
        }
        for s in h2h.sets
        for game in (s.games or [None])
    ]
    schema = {
        "date": pl.Date,
        "tournament": pl.String,
        "event": pl.String,
        "round": pl.String,
        "online": pl.Boolean,
        "game": pl.Int64,
        f"{first}_character": pl.String,
        f"{second}_character": pl.String,
        "stage": pl.String,
    }
    return TableResult.from_df(pl.DataFrame(rows, schema=schema))


def find_tournaments(  # one argument per search filter
    name: str = "",
    country: str = "",
    state: str = "",
    after: str = "",
    before: str = "",
    online: bool | None = None,
    upcoming: bool = True,
) -> TableResult:
    """Search start.gg for tournaments with a Smash Ultimate event.

    One row per Ultimate event: tournament start date, tournament, event, entrants so far,
    city, state, country, online and `event_url` (pass it to get_event_entrants). Give at
    least one filter.

    Args:
        name: text the tournament name contains, eg 'Genesis'.
        country: two-letter country code, eg 'US'.
        state: state or province code, eg 'MD' (use together with country).
        after: only tournaments starting on or after this date, eg '2026-12-01'.
        before: only tournaments starting before this date, eg '2027-01-01'.
        online: true for online tournaments, false for in-person ones; leave unset for both.
        upcoming: true (default) for upcoming tournaments, soonest first; false for past
            ones, newest first.
    """
    if not any([name.strip(), country.strip(), state.strip(), after.strip(), before.strip()]):
        raise ModelRetry("Give at least one of name, country, state, after or before.")
    page = _run(
        startgg.tournaments(
            name=name.strip(),
            country=country.strip().upper(),
            state=state.strip().upper(),
            after=_date(after, "after"),
            before=_date(before, "before"),
            online=online,
            upcoming=upcoming,
            per_page=MAX_TOURNAMENTS,
        )
    )
    rows = [
        {
            "date": t.start_at.date() if t.start_at else None,
            "tournament": t.name,
            "event": e.name,
            "entrants": e.num_entrants,
            "city": t.city,
            "state": t.state,
            "country": t.country,
            "online": e.online,
            "event_url": f"{startgg.SITE_URL}/{e.slug}",
        }
        for t in page.tournaments
        for e in t.events
    ]
    schema = {
        "date": pl.Date,
        "tournament": pl.String,
        "event": pl.String,
        "entrants": pl.Int64,
        "city": pl.String,
        "state": pl.String,
        "country": pl.String,
        "online": pl.Boolean,
        "event_url": pl.String,
    }
    table = TableResult.from_df(pl.DataFrame(rows, schema=schema))
    # more tournaments matched than the page fetched: let the model say so
    return table.model_copy(update={"truncated": page.page_info.total > len(page.tournaments)})


def get_event_entrants(event: str) -> TableResult:
    """List who is entered in a start.gg event (one bracket of a tournament).

    One row per entrant: tag, sponsor prefix and start.gg player id (usable as `player` in
    get_player_usage), in start.gg's order.

    Args:
        event: the event's page url or slug, eg
            'tournament/genesis-9/event/ultimate-singles' (find_tournaments' `event_url`),
            or a numeric event id.
    """
    page = _run(startgg.event_entrants(event, per_page=MAX_ENTRANTS))
    rows = [
        {
            "tag": player.tag,
            "prefix": player.prefix,
            "player_id": player.id,
            "entrant": entrant.name,
        }
        for entrant in page.entrants
        for player in entrant.players
    ]
    schema = {"tag": pl.String, "prefix": pl.String, "player_id": pl.Int64, "entrant": pl.String}
    table = TableResult.from_df(pl.DataFrame(rows, schema=schema))
    total = max(page.page_info.total, table.rows)
    return table.model_copy(update={"total_rows": total, "truncated": total > table.rows})


